public class Computer{String cpu,ram,storage;private Computer(Builder b){cpu=b.cpu;ram=b.ram;storage=b.storage;}public String toString(){return cpu+", "+ram+", "+storage;}static class Builder{String cpu,ram,storage;Builder cpu(String v){cpu=v;return this;}Builder ram(String v){ram=v;return this;}Builder storage(String v){storage=v;return this;}Computer build(){return new Computer(this);}}}